    fitSpline(context, id + "spline1", { "vertices" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(0, 0, 0) * millimeter), qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(30, 0, 10) * millimeter), qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(30, 20, 0) * millimeter)]), "hasStartDirection" : true, "startDirection" : qCreatedBy(id + "dirX", EntityType.EDGE), "startMagnitude" : 2 });
}

