// curve-pattern: a block patterned along an arc on a cylinder's top, locked to the top
export function c010(context is Context, id is Id)
{
    const topSketch = newSketchOnPlane(context, id + "topSketch", { "sketchPlane" : plane(vector(0, 0, -10) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(topSketch, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 40 * millimeter });
    skSolve(topSketch);
    extrude(context, id + "top", { "entities" : qSketchRegion(id + "topSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(-2, -2) * millimeter, "secondCorner" : vector(2, 2) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 4 * millimeter });
    const path = newSketchOnPlane(context, id + "path", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skArc(path, "arc1", { "start" : vector(0, 0) * millimeter, "mid" : vector(20, 8.28427) * millimeter, "end" : vector(28.28427, 28.28427) * millimeter });
    skSolve(path);
    curvePattern(context, id + "pattern1", { "entities" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), "edges" : qOwnedByBody(qBodyType(qCreatedBy(id + "path", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "spacingType" : CurvePatternSpacingType.EQUAL, "instanceCount" : 3, "orientationType" : CurvePatternOrientationType.LOCK_FACES, "lockedFaces" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "top", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(0, 0, 0) * millimeter) });
}

// sheet-metal-corner-break: a plate corner chamfered 3 mm by 6 mm
export function c011(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s1, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(s1);
    sheetMetalStart(context, id + "sm1", { "thickness" : 2 * millimeter, "oppositeDirection" : false, "radius" : 1 * millimeter, "flipDirectionUp" : false, "process" : SMProcessType.THICKEN, "regions" : qSketchRegion(id + "s1"), "tangentPropagation" : false, "bends" : qNothing() });
    sheetMetalCornerBreak(context, id + "break1", { "blendType" : EdgeBlendType.CHAMFER, "entities" : qClosestTo(qOwnedByBody(qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(40, 30, 2) * millimeter), "chamferMethod" : ChamferMethod.FACE_OFFSET, "chamferType" : ChamferType.TWO_OFFSETS, "width1" : 3 * millimeter, "width2" : 6 * millimeter, "oppositeDirection" : false });
    return { "counts" : bodyCounts(context) };
}

